def is_independence_preserving(locking_protocol, all_jobs, all_resources):
    for job_J_i in all_jobs:
        for resource_q in all_resources:
            # Assume job_J_i.get_num_requests(resource_q) returns N_i_q
            if job_J_i.get_num_requests(resource_q) == 0:
                # The protocol must guarantee that b_i_q is 0 in this case.
                # This check would typically be part of the formal analysis or proof of the protocol.
                # For a runtime check, one would need to observe blocking specific to resource_q.
                # Here, we conceptually check the protocol's analytical guarantee.
                if locking_protocol.guarantees_zero_blocking_for_unaccessed_resource(job_J_i, resource_q) == False:
                    return False
    return True

def check_no_s_oblivious_pi_blocking_for_ready_job(job_J_i, time_t, protocol_uses_mpi):
    if not protocol_uses_mpi:
        # Lemma does not apply if MPI is not used
        return None

    if job_J_i.is_ready_at(time_t):
        # According to Lemma 1, if MPI is used, a ready job does not incur s-oblivious pi-blocking.
        # This is a guaranteed property of the protocol's design.
        return False # Does not incur s-oblivious pi-blocking
    else:
        # A job that is not ready (e.g., suspended or not yet released) cannot incur pi-blocking by definition.
        return False
